INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (100, 3001100, 0, 2, 1, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 2.1, 130011, "2024/10/31 12:00:00", -416.5, 3001, "2030/01/01 14:59:59", "ヤマト");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (101, 3001101, 0, 2, 4, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 5.68, 130011, "2024/10/31 12:00:00", -416.5, 3001, "2030/01/01 14:59:59", "ヤマト");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (102, 3001102, 0, 1, 1, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 0, 130011, "2024/10/31 12:00:00", -416.5, 3001, "2030/01/01 14:59:59", "ヤマト");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (100, 3002100, 0, 1, 1, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 0, 130211, "2024/10/31 12:00:00", -416.5, 3002, "2030/01/01 14:59:59", "フブキ");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (101, 3002101, 0, 1, 1, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 0, 130211, "2024/10/31 12:00:00", -416.5, 3002, "2030/01/01 14:59:59", "フブキ");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (102, 3002102, 0, 2, 5, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 8.53, 130211, "2024/10/31 12:00:00", -416.5, 3002, "2030/01/01 14:59:59", "フブキ");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (103, 3002103, 0, 1, 7, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 5.67, 130211, "2024/10/31 12:00:00", -416.5, 3002, "2030/01/01 14:59:59", "フブキ");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (104, 3002104, 0, 1, 1, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 0, 130211, "2024/10/31 12:00:00", -416.5, 3002, "2030/01/01 14:59:59", "フブキ");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (300, 3002300, 0, 3, 3, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 0, 130211, "2024/10/31 12:00:00", -416.5, 3004, "2030/01/01 14:59:59", "フブキ");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (301, 3002400, 0, 7, 7, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 0, 130211, "2024/10/31 12:00:00", -416.5, 3005, "2030/01/01 14:59:59", "フブキ");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (200, 3003200, 0, 1, 2, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 4.4, 130211, "2024/10/31 12:00:00", -416.5, 3003, "2030/01/01 14:59:59", "フブキ");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (201, 3003201, 0, 7, 7, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 0, 130211, "2024/10/31 12:00:00", -416.5, 3003, "2030/01/01 14:59:59", "フブキ");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (202, 3003202, 0, 2, 1, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 5.6, 130211, "2024/10/31 12:00:00", -416.5, 3003, "2030/01/01 14:59:59", "フブキ");
